  antiTrad: [
    { faux: "Les parents doivent faire attention que les règles sont les mêmes.",
      juste: "Il revient aux parents de veiller à ce que les règles soient cohérentes.",
      pourquoi: "« Faire attention que » traduit « مراقب باشند که ». En français on dit « veiller à ce que » + subjonctif. Et « les mêmes » devient « cohérentes »." },
    { faux: "L'autorité donne beaucoup de bonnes choses à l'enfant.",
      juste: "L'autorité permet à l'enfant de connaître ses limites.",
      pourquoi: "« Donner beaucoup de bonnes choses » est vague. On nomme précisément ce que l'autorité rend possible." },
    { faux: "Si les parents sont trop durs, l'enfant devient peur.",
      juste: "Une discipline trop rigide peut engendrer de la peur.",
      pourquoi: "« Devenir peur » calque « ترسو می‌شود ». La peur n'est pas un état qu'on devient : elle est engendrée, provoquée, suscitée." },
    { faux: "Ce n'est pas bon de mélanger l'autorité avec la violence.",
      juste: "Confondre l'autorité et la brutalité, c'est justement l'erreur que je dénonce.",
      pourquoi: "« Mélanger » se dit d'ingrédients. Pour deux notions qu'on prend l'une pour l'autre, le verbe est « confondre »." },
    { faux: "Les parents apprennent leur méthode de leurs parents.",
      juste: "Ce modèle se transmet de génération en génération.",
      pourquoi: "La phrase persane suit les personnes ; le français d'examen préfère nommer le phénomène — « le modèle se transmet »." }
  ],

