  antiTrad: [
    { faux: "Sur Internet il y a beaucoup de choses.",
      juste: "Un site en ligne présente des milliers de références.",
      pourquoi: "« Des choses » ne dit rien. « Une référence » est le mot du commerce, et il est attendu sur ce sujet." },
    { faux: "La taille n'est pas bonne.",
      juste: "La taille ne convient pas.",
      pourquoi: "« Ne pas être bonne » est plat. « Convenir » est le verbe exact pour un vêtement." },
    { faux: "Il faut envoyer le colis encore.",
      juste: "Il faut renvoyer le colis.",
      pourquoi: "Le préfixe « re- » porte le sens de retour. « Envoyer encore » est un calque." },
    { faux: "Les vieilles personnes ne savent pas Internet.",
      juste: "Beaucoup de personnes âgées ne sont pas à l'aise avec ces démarches.",
      pourquoi: "« Les vieilles personnes » est maladroit ; « savoir Internet » n'existe pas. Le bloc est « être à l'aise avec »." },
    { faux: "On peut acheter tout ce qu'on veut sur Internet.",
      juste: "On peut acheter en ligne la plupart des produits du quotidien.",
      pourquoi: "« Tout ce qu'on veut » est trop absolu à l'examen. Nuancer rapporte des points." }
  ],

